cmds_summary:
# A local UV script uploads its own directory, not arbitrary sibling files.
# Stage exactly the input bundle; never sync the repo (which contains secrets).
STAGE=$(mktemp -d)
trap 'rm -rf "$STAGE"' EXIT
cp scripts/finetune/{train.py,measure_corpus.py,template_guard.py,langfuse_tracking.py} "$STAGE/"
cp -- "{{.CORPUS}}" "$STAGE/corpus.jsonl"
cp -- "{{.MEASURE_REPORT}}" "$STAGE/report.json"
{{if .CONFIG}}cp -- "{{.CONFIG}}" "$STAGE/config.json"{{end}}
{{if .EVAL_CORPUS}}cp -- "{{.EVAL_CORPUS}}" "$STAGE/eval.jsonl"{{end}}
{{if .HUB_TEMPLATE}}cp -- "{{.HUB_TEMPLATE}}" "$STAGE/hub.jinja"{{end}}
{{if .PATCHED_TEMPLATE}}cp -- "{{.PATCHED_TEMPLATE}}" "$STAGE/patched.jinja"{{end}}
FLAVOR="{{.FLAVOR}}"
[ -n "$FLAVOR" ] || FLAVOR=l4x1
set -- --corpus /data/corpus.jsonl --model "{{.MODEL}}" \
  --measure-report /data/report.json --hub-model-id "{{.HUB_MODEL_ID}}" \
  --report-to trackio --output-dir /tmp/finetune-output
{{if .PRECISION}}set -- "$@" --precision "{{.PRECISION}}"{{end}}
{{if .MAX_SEQ_LENGTH}}set -- "$@" --max-seq-length "{{.MAX_SEQ_LENGTH}}"{{end}}
{{if .CONFIG}}set -- "$@" --config /data/config.json{{end}}
{{if .EVAL_CORPUS}}set -- "$@" --eval-corpus /data/eval.jsonl{{end}}
{{if .HUB_TEMPLATE}}set -- "$@" --hub-template /data/hub.jinja{{end}}
{{if .PATCHED_TEMPLATE}}set -- "$@" --patched-template /data/patched.jinja{{end}}
JOB_DRY_RUN=""
{{if .DRY_RUN}}JOB_DRY_RUN="--dry-run"{{end}}
TRACKING_ARGS=()
if [ -n "${LANGFUSE_PUBLIC_KEY:-}${LANGFUSE_SECRET_KEY:-}" ]; then
  [ -n "${LANGFUSE_PUBLIC_KEY:-}" ] && [ -n "${LANGFUSE_SECRET_KEY:-}" ] || {
    echo "Both Langfuse keys are required" >&2; exit 2;
  }
  TRACKING_ARGS+=(--secrets LANGFUSE_PUBLIC_KEY --secrets LANGFUSE_SECRET_KEY --with 'langfuse>=4.7,<5')
  if [ -n "${LANGFUSE_BASE_URL:-}" ]; then
    TRACKING_ARGS+=(--env "LANGFUSE_BASE_URL=${LANGFUSE_BASE_URL}")
  fi
fi
uvx --from "huggingface_hub" hf jobs uv run \
  --flavor "$FLAVOR" --timeout 2h --detach $JOB_DRY_RUN --secrets HF_TOKEN "${TRACKING_ARGS[@]}" \
  --with unsloth --with trl --with datasets --with trackio --with torchvision \
  "$STAGE/train.py" "$@"

source scripts/env-resolve.sh "${ENV:-dev}"
ctx_flag=""
[ "${ENV:-dev}" != "dev" ] && ctx_flag="--context $ENV_CONTEXT"
NS="${WORKSPACE_NAMESPACE:-workspace}"

fuser -k 15434/tcp 2>/dev/null || true
kubectl $ctx_flag -n "$NS" port-forward svc/shared-db 15434:5432 \
  >/tmp/scs-search-pf.log 2>&1 &
PF=$!
trap 'kill $PF 2>/dev/null || true' EXIT
sleep 4

PGHOST=localhost PGPORT=15434 PGDATABASE=website PGUSER=website \
  npx tsx -e "
    import { searchCode, searchCodeAugmented } from './components/website/src/lib/codesearch-db.ts';
    const args = process.argv.slice(1);
    const q = args[0];
    const augmented = args.includes('--augmented');
    const limitMatch = args.find(a => a.startsWith('--limit='));
    const limit = limitMatch ? parseInt(limitMatch.split('=')[1]) : 5;
    const fn = augmented ? searchCodeAugmented : searchCode;
    fn(q, limit).then(r => console.log(JSON.stringify(r, null, 2))).catch(e => { console.error(e.message); process.exit(1); });
  " {{.CLI_ARGS}}

source scripts/env-resolve.sh "{{.ENV}}"
if ! kubectl --context "$ENV_CONTEXT" cluster-info >/dev/null 2>&1; then
  echo "No cluster reachable for ENV={{.ENV}} context $ENV_CONTEXT" >&2; exit 1
fi

helm repo add jetstack https://charts.jetstack.io --force-update
helm repo update

helm upgrade --install cert-manager jetstack/cert-manager \
  --namespace cert-manager --create-namespace \
  --kube-context "$ENV_CONTEXT" \
  --set crds.enabled=true \
  --set podDnsPolicy=Default \
  --wait --timeout=180s

kubectl patch deploy -n cert-manager cert-manager --context "$ENV_CONTEXT" \
  --type=merge -p '{"spec":{"template":{"spec":{"dnsPolicy":"Default"}}}}' \
  2>/dev/null || true

kubectl patch deploy -n cert-manager cert-manager --context "$ENV_CONTEXT" \
  --type=merge -p '{
    "spec":{"template":{"spec":{"affinity":{"nodeAffinity":{
      "requiredDuringSchedulingIgnoredDuringExecution":{
        "nodeSelectorTerms":[{"matchExpressions":[{
          "key":"kubernetes.io/hostname",
          "operator":"In",
          "values":["gekko-hetzner-2","gekko-hetzner-3","gekko-hetzner-4","pk-hetzner-4","pk-hetzner-6","pk-hetzner-8"]
        }]}]
      }
    }}}}}
  }' 2>/dev/null || true

helm repo add cert-manager-lego-webhook https://yxwuxuanl.github.io/cert-manager-lego-webhook/ --force-update
helm repo update

helm upgrade --install cert-manager-lego-webhook cert-manager-lego-webhook/cert-manager-lego-webhook \
  --namespace cert-manager \
  --kube-context "$ENV_CONTEXT" \
  --set certManager.namespace=cert-manager \
  --set certManager.serviceAccountName=cert-manager \
  --wait --timeout=120s

kubectl patch deploy -n cert-manager cert-manager-lego-webhook --context "$ENV_CONTEXT" \
  --type=merge -p '{
    "spec":{"template":{"spec":{"affinity":{"nodeAffinity":{
      "requiredDuringSchedulingIgnoredDuringExecution":{
        "nodeSelectorTerms":[{"matchExpressions":[{
          "key":"kubernetes.io/hostname",
          "operator":"In",
          "values":["gekko-hetzner-2","gekko-hetzner-3","gekko-hetzner-4","pk-hetzner-4","pk-hetzner-6","pk-hetzner-8"]
        }]}]
      }
    }}}}}
  }' 2>/dev/null || true

# Wire IPV64_API_KEY from sealed secret into webhook — idempotent;
# no-op when cert:secret hasn't run yet (key secret absent).
if kubectl --context "$ENV_CONTEXT" get secret ipv64-api-key -n cert-manager >/dev/null 2>&1; then
  kubectl --context "$ENV_CONTEXT" set env deployment/cert-manager-lego-webhook -n cert-manager --from=secret/ipv64-api-key
  echo "✓ IPV64_API_KEY wired into cert-manager-lego-webhook from ipv64-api-key secret"
else
  echo "ℹ IPV64_API_KEY not yet available — run cert:secret after sealing"
fi

[ -d node_modules ] || npm ci
./node_modules/.bin/playwright install chromium >/dev/null 2>&1 || true
./node_modules/.bin/playwright test --project=website {{.CLI_ARGS}}

[ -d node_modules ] || npm ci
./node_modules/.bin/playwright install chromium >/dev/null 2>&1 || true
./node_modules/.bin/playwright test --project=services {{.CLI_ARGS}}

[ -d node_modules ] || npm ci
./node_modules/.bin/playwright install chromium >/dev/null 2>&1 || true
./node_modules/.bin/playwright test --project=brett-mentolder {{.CLI_ARGS}}

case "{{.ENV}}" in
  mentolder)  export PROD_DOMAIN=mentolder.de ;;
  korczewski) export PROD_DOMAIN=korczewski.de ;;
esac
export ENV="{{.ENV}}"
[ -d node_modules ] || npm ci
./node_modules/.bin/playwright install chromium >/dev/null 2>&1 || true
node scripts/web-audit.mjs --brand "{{.ENV}}" {{.CLI_ARGS}}
